public class AccountManager {
    private Account primary;
    private Account backup = new Account("Backup", 100.0);

    static class Account {
        private String name;
        private double balance;

        public Account(String name, double balance) {
            this.name = name;
            if (balance > 0.0) {
                this.balance = balance;
            }
        }

        public double transferTo(Account target, double amount) {
            if (amount > 0.0 && amount <= balance) {
                balance = balance - amount;
                target.balance = target.balance + amount;
            }
            return balance;
        }
    }

    public static void main(String[] args) {
        AccountManager mgr = new AccountManager();
        double remaining = mgr.backup.transferTo(mgr.primary, 40.0);
        System.out.printf("%.2f", remaining);
    }
}

public class Account {
    private String name;
    private double balance;

    public Account(String name, double balance) {
        this.name = name;
        if (balance > 0.0) {
            this.balance = balance;
        }
    }

    public double applyBonus(int ratePercent) {
        double bonus = (ratePercent / 100) * balance;
        balance = balance + bonus;
        return balance;
    }

    public double applyBonus(double ratePercent) {
        double bonus = (ratePercent / 100) * balance;
        balance = balance + bonus;
        return balance;
    }

    public static void main(String[] args) {
        Account acc = new Account("Savings", 200.0);
        System.out.printf("%.2f %.2f %.2f",
            acc.applyBonus(50),
            acc.applyBonus(10.0),
            acc.balance);
    }
}
